  (NULL, NULL, 'Shoulder Mobility Flow', 'Increase shoulder range of motion and reduce injury risk.', '1. Arm circles forward 10 reps\n2. Arm circles backward 10 reps\n3. Cross-body shoulder stretch 10 sec per side\n4. Behind-back shoulder reach 10 sec per side', 'mobility', ARRAY['setter', 'outside_hitter', 'opposite', 'middle_blocker'], 'beginner', ARRAY['general'], ARRAY['exercise mat'], 'https://www.youtube.com/results?search_query=volleyball+shoulder+mobility+stretch', NULL, '["Controlled movements", "No bouncing", "Deep stretch", "Breathe slowly"]'::jsonb, true),

  (NULL, NULL, 'Hip and Hamstring Flexibility', 'Improve lower body flexibility for better range of motion and power.', '1. Quad stretch 20 seconds per leg\n2. Hamstring stretch 20 seconds per leg\n3. Pigeon pose 30 seconds per side\n4. Deep squat hold 30 seconds', 'mobility', ARRAY['setter', 'libero', 'outside_hitter', 'opposite', 'middle_blocker', 'defensive_specialist'], 'beginner', ARRAY['general'], ARRAY['exercise mat'], 'https://www.youtube.com/results?search_query=volleyball+hip+hamstring+flexibility+stretch', NULL, '["Controlled breathing", "No pain", "Hold steady", "Progressive depth"]'::jsonb, true),

  (NULL, NULL, 'Ankle Mobility Series', 'Strengthen ankles and improve mobility for stability and injury prevention.', '1. Ankle circles both directions 10 times\n2. Heel-to-toe walks 20 meters\n3. Single-leg balance 30 seconds per leg\n4. Calf raises 15 reps', 'mobility', ARRAY['setter', 'libero', 'outside_hitter', 'opposite', 'middle_blocker', 'defensive_specialist'], 'beginner', ARRAY['general'], ARRAY['exercise mat', 'cones'], 'https://www.youtube.com/results?search_query=volleyball+ankle+mobility+exercises', NULL, '["Full range motion", "Control movement", "Balance challenge", "Strength focus"]'::jsonb, true),

  (NULL, NULL, 'Full Body Dynamic Warm-Up', 'Comprehensive warm-up combining mobility and activation for all movement planes.', '1. Arm circles and band pull-aparts\n2. Leg swings forward/back and side-to-side\n3. Walking lunges with rotation\n4. Inchworms and push-up to downward dog\n5. Light jumping jacks and shuffles', 'mobility', ARRAY['setter', 'libero', 'outside_hitter', 'opposite', 'middle_blocker', 'defensive_specialist'], 'beginner', ARRAY['general'], ARRAY['resistance band', 'exercise mat'], 'https://www.youtube.com/results?search_query=volleyball+dynamic+warm+up+routine', NULL, '["Gradual intensity increase", "Full range motion", "Smooth transitions", "Breathing control"]'::jsonb, true);

